using namespace std;

int main() {
    long long a, b, p;
    cin >> a >> b >> p;
    long long best = p + 1;
    // Enumerate the number of a-sized teams; the rest must split evenly into b-sized teams.
    for (long long x = 0; x <= p / a; x++) {
        long long rest = p - a * x;
        if (rest % b == 0) best = min(best, x + rest / b);
    }
