import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong(), b = sc.nextLong(), p = sc.nextLong();
        long best = p + 1;
        // Enumerate the number of a-sized teams; the rest must split evenly into b-sized teams.
        for (long x = 0; x <= p / a; x++) {
            long rest = p - a * x;
            if (rest % b == 0) best = Math.min(best, x + rest / b);
        }
        System.out.println(best <= p ? best : -1);
    }
}

package main

import "fmt"

func main() {
	var a, b, p int64
	fmt.Scan(&a, &b, &p)
	best := p + 1
	// Enumerate the number of a-sized teams; the rest must split evenly into b-sized teams.
	for x := int64(0); x <= p/a; x++ {
		rest := p - a*x
		if rest%b == 0 {
			best = min(best, x+rest/b)
		}
	}
	if best > p {
		best = -1
	}
	fmt.Println(best)
